#!/bin/bash
fecha=$(date) usuario=$(whoami) directorio=$(pwd) espacio=$(df / | tail -1 | awk '{print $5}')
echo "Fecha: $fecha | Usuario: $usuario | Dir: $directorio | Espacio: $espacio"

import shutil
total, used, free = shutil.disk_usage('/') percent_used = (used / total) * 100
if percent_used > 80: print("ALERTA: Disco lleno") else: print(f"Espacio suficiente: {percent_used:.1f}% usado")

import psutil

alertas = []

cpu = psutil.cpu_percent(interval=1)
if cpu > 80:
    alertas.append("ALERTA CPU")

memoria = psutil.virtual_memory()
if memoria.percent > 85:
    alertas.append("ALERTA MEMORIA")

disco = psutil.disk_usage('/')
if (disco.used / disco.total) * 100 > 90:
    alertas.append("ALERTA DISCO")

if alertas:
    for alerta in alertas:
        print(alerta)
else:
    print("Sistema normal")
